email_demo.css:
:root {
  --bg: #f6f8fc;
  --card: #ffffff;
  --text: #202124;
  --muted: #5f6368;
  --border: #dadce0;
  --blue: #1a73e8;
  --danger: #b3261e;
  --danger-bg: #fce8e6;
  --sidebar: #eef3fd;
  --hover: #f2f6fc;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

.training-banner {
  background: var(--danger-bg);
  color: var(--danger);
  border-bottom: 2px solid var(--danger);
  font-weight: 700;
  text-align: center;
  padding: 12px 16px;
}

.app {
  display: grid;
  grid-template-columns: 250px 1fr;
  min-height: calc(100vh - 46px);
}

.sidebar {
  background: var(--sidebar);
  padding: 18px 14px;
  border-right: 1px solid var(--border);
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 28px;
  padding-left: 8px;
}

.logo-icon {
  width: 34px;
  height: 24px;
  border: 3px solid #ea4335;
  border-radius: 5px;
  position: relative;
  background: #fff;
}

.logo-icon::before,
.logo-icon::after {
  content: "";
  position: absolute;
  top: 1px;
  width: 18px;
  height: 3px;
  background: #ea4335;
  transform-origin: left center;
}

.logo-icon::before {
  left: 0;
  transform: rotate(34deg);
}

.logo-icon::after {
  right: -2px;
  transform: rotate(146deg);
}

.compose {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: #c2e7ff;
  border: none;
  border-radius: 16px;
  padding: 14px 22px;
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 18px;
  cursor: default;
}

.nav-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 999px;
  color: #3c4043;
  font-size: 15px;
  margin-bottom: 4px;
}

.nav-item.active {
  background: #d3e3fd;
  color: #001d35;
  font-weight: 700;
}

.main {
  display: grid;
  grid-template-rows: auto auto 1fr;
  min-width: 0;
}

.topbar {
  height: 72px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 24px;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}

.search {
  width: min(720px, 100%);
  border: none;
  background: #eaf1fb;
  border-radius: 999px;
  padding: 15px 20px;
  font-size: 16px;
  outline: none;
}

.account-bubble {
  margin-left: auto;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #7b1fa2;
  color: white;
  display: grid;
  place-items: center;
  font-weight: 700;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 24px;
  border-bottom: 1px solid var(--border);
  background: #fff;
  color: var(--muted);
  font-size: 14px;
}

.checkbox {
  width: 18px;
  height: 18px;
  border: 2px solid #9aa0a6;
  border-radius: 3px;
}

.inbox {
  background: #fff;
  margin: 0 18px 18px;
  border: 1px solid var(--border);
  border-top: none;
  border-radius: 0 0 18px 18px;
  overflow: hidden;
}

.email-row {
  display: grid;
  grid-template-columns: 36px 180px 1fr 90px;
  gap: 12px;
  align-items: center;
  padding: 14px 18px;
  border-bottom: 1px solid #edf0f2;
  cursor: pointer;
  text-decoration: none;
  color: inherit;
}

.email-row:hover {
  background: var(--hover);
  box-shadow: inset 3px 0 0 var(--danger);
}

.sender {
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.subject-line {
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.subject {
  font-weight: 700;
}

.snippet {
  color: var(--muted);
}

.time {
  font-size: 13px;
  color: var(--muted);
  text-align: right;
  white-space: nowrap;
}

.star {
  color: #9aa0a6;
  font-size: 20px;
}

.email-detail {
  display: none;
  padding: 28px;
  border-top: 1px solid var(--border);
  background: #fff;
}

.email-detail.show {
  display: block;
}

.detail-card {
  max-width: 860px;
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 24px;
  box-shadow: 0 4px 16px rgba(60,64,67,0.08);
}

.detail-subject {
  font-size: 26px;
  margin-bottom: 20px;
}

.detail-from {
  color: var(--muted);
  margin-bottom: 20px;
}

.detail-body {
  font-size: 16px;
  line-height: 1.65;
  color: #303134;
}

.phish-button {
  display: inline-block;
  margin-top: 18px;
  background: var(--blue);
  color: white;
  text-decoration: none;
  border-radius: 999px;
  padding: 12px 22px;
  font-weight: 700;
}

.warning-note {
  margin-top: 22px;
  background: var(--danger-bg);
  color: var(--danger);
  border: 1px solid #f1c0c0;
  border-radius: 14px;
  padding: 14px;
  font-weight: 700;
  display: none;
}

.warning-note.show {
  display: block;
}

@media (max-width: 850px) {
  .app {
    grid-template-columns: 1fr;
  }

  .sidebar {
    display: none;
  }

  .email-row {
    grid-template-columns: 28px 120px 1fr;
  }

  .time {
    display: none;
  }
}

phishing_demo_1.css:
:root {
  --bg: #f0f4f9;
  --card: #ffffff;
  --text: #1f1f1f;
  --muted: #5f6368;
  --blue: #0b57d0;
  --border: #dadce0;
  --danger: #b3261e;
  --warn-bg: #fce8e6;
  --good-bg: #e6f4ea;
  --good: #137333;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: linear-gradient(180deg, #eaf2ff 0%, var(--bg) 35%, #eef3f8 100%);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.page {
  width: 100%;
  max-width: 1180px;
  display: grid;
  grid-template-columns: 1.2fr 0.9fr;
  gap: 24px;
  align-items: start;
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 28px;
  box-shadow: 0 8px 30px rgba(32, 33, 36, 0.08);
}

.demo-card {
  padding: 18px;
  overflow: hidden;
}

.training-banner {
  margin-bottom: 16px;
  border: 2px solid var(--danger);
  background: var(--warn-bg);
  color: var(--danger);
  border-radius: 16px;
  padding: 14px 16px;
  font-weight: 700;
  text-align: center;
  letter-spacing: 0.2px;
}

.browser {
  border: 1px solid var(--border);
  border-radius: 22px;
  overflow: hidden;
  background: #fff;
}

.browser-top {
  background: #f8f9fa;
  border-bottom: 1px solid var(--border);
  padding: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.dots {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #c4c7c5;
}

.address-bar {
  flex: 1;
  background: #eef3fd;
  border: 1px solid #d2e3fc;
  color: #8d2d25;
  border-radius: 999px;
  padding: 10px 14px;
  font-size: 14px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.browser-content {
  padding: 18px;
  background: #f8fbff;
}

.email-lure {
  border: 1px solid #f3c7c3;
  background: #fff8f7;
  border-radius: 18px;
  padding: 16px;
  margin-bottom: 18px;
}

.email-lure .from {
  font-size: 14px;
  color: var(--muted);
  margin-bottom: 8px;
}

.email-lure .subject {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 10px;
}

.email-lure .body {
  color: #3c4043;
  line-height: 1.5;
  font-size: 15px;
}

.fake-login {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 36px 32px 28px;
  max-width: 540px;
  margin: 0 auto;
}

.logo {
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -0.6px;
  margin-bottom: 12px;
}

.logo .b { color: #4285f4; }
.logo .r { color: #db4437; }
.logo .y { color: #f4b400; }
.logo .g { color: #4285f4; }
.logo .g2 { color: #0f9d58; }
.logo .r2 { color: #db4437; }

.login-title {
  font-size: 32px;
  line-height: 1.2;
  margin-bottom: 10px;
}

.login-subtitle {
  font-size: 16px;
  color: var(--muted);
  margin-bottom: 22px;
}

.danger-callout {
  background: #fff5f5;
  border: 1px solid #f1c0c0;
  color: var(--danger);
  border-radius: 14px;
  padding: 12px 14px;
  font-size: 14px;
  margin-bottom: 18px;
  font-weight: 700;
}

.field {
  width: 100%;
  padding: 16px 14px;
  border: 1px solid #a8c7fa;
  border-radius: 4px;
  font-size: 16px;
  margin-bottom: 14px;
  outline: none;
  background: #fff;
}

.small-link {
  color: var(--blue);
  font-size: 14px;
  margin-bottom: 20px;
  display: inline-block;
  text-decoration: none;
  font-weight: 600;
  cursor: pointer;
}

.helper {
  font-size: 14px;
  color: var(--muted);
  line-height: 1.5;
  margin-bottom: 20px;
}

.actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 6px;
}

.btn-link {
  background: transparent;
  border: none;
  color: var(--blue);
  font-weight: 600;
  font-size: 14px;
  padding: 10px 8px;
  cursor: pointer;
}

.btn-primary {
  border: none;
  background: var(--blue);
  color: #fff;
  font-weight: 700;
  font-size: 14px;
  border-radius: 999px;
  padding: 11px 24px;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(0,0,0,0.16);
}

.panel {
  padding: 24px;
}

.panel h2 {
  margin: 0 0 10px;
  font-size: 28px;
  line-height: 1.2;
}

.panel p.lead {
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.55;
}

.score {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--good-bg);
  color: var(--good);
  border: 1px solid #c6e7cb;
  border-radius: 999px;
  padding: 10px 14px;
  font-weight: 700;
  margin-bottom: 18px;
}

.flags {
  display: grid;
  gap: 12px;
  margin-bottom: 18px;
}

.flag {
  display: grid;
  grid-template-columns: 34px 1fr;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: #fff;
}

.flag-num {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #e8f0fe;
  color: var(--blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

.flag h3 {
  margin: 0 0 4px;
  font-size: 16px;
}

.flag p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
}

.teacher-box {
  margin-top: 12px;
  background: #f8f9fa;
  border: 1px dashed #bcc0c4;
  border-radius: 16px;
  padding: 16px;
}

.teacher-box h3 {
  margin: 0 0 8px;
  font-size: 16px;
}

.teacher-box ul {
  margin: 0;
  padding-left: 20px;
  color: #3c4043;
  line-height: 1.5;
}

.reveal {
  margin-top: 18px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.reveal button {
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 600;
  cursor: pointer;
}

.result {
  margin-top: 16px;
  border-radius: 16px;
  padding: 14px 16px;
  font-size: 15px;
  line-height: 1.5;
  display: none;
}

.result.show {
  display: block;
}

.result.bad {
  background: #fff5f5;
  border: 1px solid #f1c0c0;
  color: #7a1f18;
}

.result.good {
  background: #eef7ee;
  border: 1px solid #c7e4cb;
  color: #1f5f2d;
}

.footer-note {
  margin-top: 16px;
  font-size: 13px;
  color: var(--muted);
}

@media (max-width: 980px) {
  .page {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  body { padding: 12px; }
  .demo-card, .panel { padding: 14px; }
  .fake-login { padding: 24px 18px; }
  .login-title { font-size: 26px; }
  .panel h2 { font-size: 24px; }
  .actions { flex-direction: column; align-items: stretch; }
  .btn-primary { width: 100%; }
}
